allocation_probe_source:
/* Linux/glibc-only counting probe. Timings from this preload are not used. */
#include <stddef.h>
#include <stdio.h>
#include <unistd.h>
extern void *__libc_malloc(size_t);
extern void *__libc_calloc(size_t,size_t);
extern void *__libc_realloc(void *,size_t);
extern void __libc_free(void *);
static unsigned long long nm,nc,nr,nf,bytes;
void *malloc(size_t n) { ++nm; bytes+=n; return __libc_malloc(n); }
void *calloc(size_t n,size_t m) { ++nc; bytes+=n*m; return __libc_calloc(n,m); }
void *realloc(void *p,size_t n) { ++nr; bytes+=n; return __libc_realloc(p,n); }
void free(void *p) { if(p) ++nf; __libc_free(p); }
__attribute__((destructor)) static void report(void) {
    char line[256];
    int n=snprintf(line,sizeof(line),"ALLOC malloc=%llu calloc=%llu realloc=%llu free=%llu requested_bytes=%llu\n",nm,nc,nr,nf,bytes);
    write(2,line,n);
}

